package org.rhythmlab.assist;
import android.app.*;import android.content.*;import android.graphics.*;import android.media.MediaPlayer;import android.net.Uri;import android.os.Bundle;import android.view.*;import android.widget.*;import java.io.*;import java.util.*;
/** Independent resource workshop. All files are owned by this module, never the host. */
public final class Dashboard extends Activity {
 private LinearLayout page;private TextView state;private SkinArchive selected;private boolean busy,alive=true;private MediaPlayer player;private File preview;
 private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}
 private TextView text(String value,int size){TextView t=new TextView(this);t.setText(value);t.setTextColor(0xff233349);t.setTextSize(size);t.setLineSpacing(dp(3),1);t.setPadding(0,dp(6),0,dp(8));return t;}
 private LinearLayout card(String title){LinearLayout c=new LinearLayout(this);c.setOrientation(1);c.setPadding(dp(16),dp(12),dp(16),dp(12));android.graphics.drawable.GradientDrawable bg=new android.graphics.drawable.GradientDrawable();bg.setColor(0xffffffff);bg.setCornerRadius(dp(14));c.setBackground(bg);LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(-1,-2);p.bottomMargin=dp(12);page.addView(c,p);TextView h=text(title,18);h.setTypeface(null,1);c.addView(h);return c;}
 private void button(LinearLayout c,String label,Runnable action){Button b=new Button(this);b.setText(label);b.setAllCaps(false);b.setTextColor(0xff205bbb);b.setBackgroundTintList(android.content.res.ColorStateList.valueOf(0xffeaf2ff));c.addView(b,new LinearLayout.LayoutParams(-1,dp(50)));b.setOnClickListener(v->{if(!busy)action.run();else Toast.makeText(this,"正在检查，请稍候",Toast.LENGTH_SHORT).show();});}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);render();Notice.show(this,()->{String id=getPreferences(0).getString("selected","");if(id.matches("[0-9a-f-]{36}"))open(new File(home(),id+".zip"));});}
 private File home(){return new File(getFilesDir(),"skin-inspections");}
 private void render(){ScrollView scroll=new ScrollView(this);scroll.setBackgroundColor(0xfff2f6fc);page=new LinearLayout(this);page.setOrientation(1);page.setPadding(dp(18),dp(20),dp(18),dp(24));scroll.addView(page);setContentView(scroll);page.addView(text(Target.NAME+" · 使用辅助",28));page.addView(text("纯辅助0.1.0 · "+Target.HOST,13));
  LinearLayout game=card("游戏内辅助");game.addView(text("启用LSPosed模块并仅勾选目标游戏，冷启动后长按音量上键打开。提供窗口亮度、前台常亮和Android界面回调采样。不会自动打开面板，不会产生游戏触摸。",14));button(game,"打开 "+Target.NAME,()->{try{Intent i=getPackageManager().getLaunchIntentForPackage(Target.HOST);if(i==null)throw new IllegalStateException("未找到目标游戏");startActivity(i);}catch(RuntimeException e){error(e.getMessage());}});
  LinearLayout skin=card("皮肤资源工作台");skin.addView(text(Target.PHIRA?"为Phira原生皮肤管理补充包结构检查、长条图集核对、图片/音效预览。检查后导出，再由Phira原生功能导入。":"检查和预览标准Phira音符资源包，为Phigros的显示适配准备资源。当前没有接入Phigros游戏内换肤；不能把预览当作已应用。",14));button(skin,"选择皮肤 ZIP 并检查",()->startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("*/*"),11));button(skin,"打开已检查副本",this::choose);state=text(selected==null?"尚未选择皮肤。原文件不会被覆盖。":selected.name+" · "+selected.author+"\n"+selected.report,14);state.setTextIsSelectable(true);skin.addView(state);
  if(selected!=null){button(skin,"预览图片",()->pick(selected.images,false));button(skin,"试听音效",()->pick(selected.audio,true));button(skin,"查看元数据",()->{if(selected.texts.isEmpty())return;new AlertDialog.Builder(this).setTitle("只读元数据").setItems(selected.texts.toArray(new String[0]),(d,i)->{try{TextView t=text(new String(selected.read(selected.texts.get(i),65536),"UTF-8"),14);t.setTextIsSelectable(true);ScrollView s=new ScrollView(this);s.addView(t);new AlertDialog.Builder(this).setTitle(selected.texts.get(i)).setView(s).setPositiveButton("关闭",null).show();}catch(Exception e){error(e.getMessage());}}).setNegativeButton("取消",null).show();});button(skin,"导出检查副本（不转换格式）",()->startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/zip").putExtra(Intent.EXTRA_TITLE,"skin-checked.zip"),12));button(skin,"删除此检查副本",()->new AlertDialog.Builder(this).setTitle("仅删除模块内副本").setMessage("不会删除最初选择的原文件。").setPositiveButton("删除",(d,w)->{if(selected.file.delete()){selected=null;getPreferences(0).edit().remove("selected").apply();render();}else error("副本删除失败");}).setNegativeButton("取消",null).show());}
  LinearLayout notice=card("使用说明与免责声明");notice.addView(text(Notice.TEXT,14));notice.addView(text("模块无网络、存储全盘访问或系统悬浮窗权限。检查文件由你通过系统文件选择器授权。宿主游戏联网保持原样。",13));
 }
 private void choose(){File[] files=home().listFiles((d,n)->n.matches("[0-9a-f-]{36}\\.zip"));if(files==null||files.length==0){error("暂无副本");return;}String[] labels=new String[files.length];for(int i=0;i<files.length;i++)labels[i]=files[i].getName()+" · "+files[i].length()/1024+" KB";new AlertDialog.Builder(this).setTitle("已检查副本").setItems(labels,(d,i)->open(files[i])).setNegativeButton("取消",null).show();}
 private void open(File file){busy=true;if(state!=null)state.setText("正在检查资源…");new Thread(()->{try{SkinArchive p=SkinArchive.open(file);runOnUiThread(()->{busy=false;if(!alive)return;selected=p;getPreferences(0).edit().putString("selected",file.getName().substring(0,36)).apply();render();});}catch(Exception e){runOnUiThread(()->{busy=false;if(alive){error(e.getMessage());render();}});}},"AssistSkinCheck").start();}
 @Override protected void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();if(request==11){busy=true;state.setText("正在复制并检查皮肤…");new Thread(()->{File file=null;try{File dir=home();if(!dir.isDirectory()&&!dir.mkdirs())throw new IOException("无法创建检查目录");File[] old=dir.listFiles();long total=0;int count=0;if(old!=null)for(File f:old){total+=f.length();count++;}if(count>=20||total>192L*1024*1024)throw new IOException("检查副本已到容量上限，请先删除不需要的副本");file=new File(dir,UUID.randomUUID()+".zip");try(InputStream in=getContentResolver().openInputStream(uri);OutputStream out=new FileOutputStream(file)){if(in==null)throw new IOException("无法读取所选文件");copy(in,out,64L*1024*1024);}SkinArchive p=SkinArchive.open(file);File completed=file;runOnUiThread(()->{busy=false;if(!alive)return;selected=p;getPreferences(0).edit().putString("selected",completed.getName().substring(0,36)).apply();render();});}catch(Exception e){if(file!=null)file.delete();runOnUiThread(()->{busy=false;if(alive){error(e.getMessage());render();}});}},"AssistSkinImport").start();}else if(request==12&&selected!=null){try(InputStream in=new FileInputStream(selected.file);OutputStream out=getContentResolver().openOutputStream(uri,"w")){if(out==null)throw new IOException("无法创建导出文件");copy(in,out,64L*1024*1024);Toast.makeText(this,"已导出原字节副本；请在目标游戏中手动导入",Toast.LENGTH_LONG).show();}catch(Exception e){error(e.getMessage());}}}
 private static void copy(InputStream in,OutputStream out,long max)throws IOException{byte[] b=new byte[16384];long size=0;int n;while((n=in.read(b))!=-1){size+=n;if(size>max)throw new IOException("文件超过允许体积");out.write(b,0,n);}}
 private void pick(List<String> names,boolean sound){if(names.isEmpty()){error("包内没有此类资源");return;}new AlertDialog.Builder(this).setTitle(sound?"选择试听音效":"选择预览图片").setItems(names.toArray(new String[0]),(d,i)->{try{byte[] bytes=selected.read(names.get(i),32*1024*1024);if(sound)play(bytes,names.get(i));else image(bytes,names.get(i));}catch(Exception e){error(e.getMessage());}}).setNegativeButton("取消",null).show();}
 private void image(byte[] bytes,String name)throws IOException{BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(o.outWidth<1||o.outHeight<1||o.outWidth>4096||o.outHeight>4096)throw new IOException("图片无效或超过4096像素");o.inSampleSize=1;while(Math.max(o.outWidth,o.outHeight)/o.inSampleSize>1200)o.inSampleSize*=2;o.inJustDecodeBounds=false;Bitmap b=BitmapFactory.decodeByteArray(bytes,0,bytes.length,o);if(b==null)throw new IOException("图片无法解码");ImageView image=new ImageView(this);image.setBackgroundColor(0xffdce4ee);image.setScaleType(ImageView.ScaleType.FIT_CENTER);image.setImageBitmap(b);AlertDialog shown=new AlertDialog.Builder(this).setTitle(name).setView(image).setPositiveButton("关闭",null).create();shown.setOnDismissListener(d->{image.setImageDrawable(null);b.recycle();});shown.show();shown.getWindow().setLayout(Math.min(dp(640),getResources().getDisplayMetrics().widthPixels-dp(24)),Math.min(dp(460),getResources().getDisplayMetrics().heightPixels-dp(24)));}
 private void stopAudio(){if(player!=null){player.release();player=null;}if(preview!=null){preview.delete();preview=null;}}
 private void play(byte[] bytes,String name)throws Exception{stopAudio();String ext=name.substring(name.lastIndexOf('.'));preview=new File(getCacheDir(),"assist-preview"+ext);try(OutputStream out=new FileOutputStream(preview)){out.write(bytes);}player=new MediaPlayer();player.setDataSource(preview.getAbsolutePath());MediaPlayer current=player;player.setOnPreparedListener(p->{if(alive&&player==p)p.start();});player.setOnCompletionListener(p->{if(player==p)stopAudio();});player.setOnErrorListener((p,a,b)->{if(player==p){stopAudio();if(alive)error("音频无法解码");}return true;});player.prepareAsync();new AlertDialog.Builder(this).setTitle("试听："+name).setMessage("仅在资源工具内播放，不替换游戏音效。").setPositiveButton("停止",(d,w)->{if(player==current)stopAudio();}).setOnCancelListener(d->{if(player==current)stopAudio();}).show();}
 private void error(String message){new AlertDialog.Builder(this).setTitle("辅助工具提示").setMessage(message==null?"操作失败":message).setPositiveButton("知道了",null).show();}
 @Override protected void onDestroy(){alive=false;stopAudio();super.onDestroy();}
 @Override protected void onPause(){stopAudio();super.onPause();}
}
